<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class WorkOrder extends Model {
    protected $fillable=['uuid','tracking_token','tracking_enabled','work_order_number','external_reference','creation_source','source_system','vendor_organization_id','showroom_id','zone_id','zonal_manager_id','applicator_id','external_verifier_id','vehicle_id','package_code','job_type','requested_at','scheduled_at','status','pricing_amount','pricing_currency','pricing_snapshot','notes','submitted_at','approved_at','closed_at','parent_work_order_id','origin_rework_id','relationship_type'];
    protected function casts(): array {return ['tracking_enabled'=>'boolean','requested_at'=>'datetime','scheduled_at'=>'datetime','submitted_at'=>'datetime','approved_at'=>'datetime','closed_at'=>'datetime','pricing_snapshot'=>'array','pricing_amount'=>'decimal:2'];}
    public function vehicle(){return $this->belongsTo(Vehicle::class);} public function showroom(){return $this->belongsTo(Showroom::class);} public function zone(){return $this->belongsTo(Zone::class);} public function zonalManager(){return $this->belongsTo(User::class,'zonal_manager_id');} public function applicator(){return $this->belongsTo(User::class,'applicator_id');} public function verifier(){return $this->belongsTo(User::class,'external_verifier_id');} public function assignments(){return $this->hasMany(Assignment::class);} public function evidence(){return $this->hasMany(EvidenceItem::class);} public function checkins(){return $this->hasMany(Checkin::class);} public function events(){return $this->hasMany(WorkEvent::class);} public function complaints(){return $this->hasMany(Complaint::class);} public function payment(){return $this->hasOne(Payment::class);} public function parentWorkOrder(){return $this->belongsTo(WorkOrder::class,'parent_work_order_id');} public function childWorkOrders(){return $this->hasMany(WorkOrder::class,'parent_work_order_id');}
}
